/// <summary>
/// Base class for PricingAttribute table <c>WHSProductVariantFixedLocation</c>.
/// </summary>
internal abstract class GUPPricingAttributeWHSProductVariantFixedLocation extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected WHSProductVariantFixedLocation getTableRecord(Common _pricingObject)
    {
        SalesLine                      salesLine = _pricingObject as SalesLine;
        WHSProductVariantFixedLocation wHSProductVariantFixedLocation;
        InventDim                      inventDim;

        if (salesLine.ItemId)
        {
            inventDim                      = salesLine.inventDim();
            wHSProductVariantFixedLocation = this.wHSProductVariantFixedLocation(salesLine.ItemId,
                                                                                 inventDim.inventDimId,
                                                                                 inventDim.InventLocationId,
                                                                                 inventDim.wMSLocationId);
        }
        
        return wHSProductVariantFixedLocation;
    }

    private WHSProductVariantFixedLocation wHSProductVariantFixedLocation(ItemId            _itemId,
                                                                          InventDimId       _productVariantInventDimId,
                                                                          InventLocationId  _inventLocationId,
                                                                          WMSLocationId     _wmsLocationId)
    {
        WHSProductVariantFixedLocation wHSProductVariantFixedLocation;

        if (_itemId && _productVariantInventDimId && _inventLocationId && _wmsLocationId)
        {
            select firstOnly wHSProductVariantFixedLocation
                where wHSProductVariantFixedLocation.ItemId                    == _itemId
                   && wHSProductVariantFixedLocation.ProductVariantInventDimId == _productVariantInventDimId
                   && wHSProductVariantFixedLocation.InventLocationId          == _inventLocationId
                   && wHSProductVariantFixedLocation.WMSLocationId             == _wmsLocationId;
        }

        return wHSProductVariantFixedLocation;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbds, qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(InventTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbds = qbdsRoot.addDataSource(tableNum(WHSProductVariantFixedLocation));
            qbds.addLink(fieldNum(InventTable, ItemId), fieldNum(WHSProductVariantFixedLocation, ItemId));
            qbds.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
            }
        }

        return qbds;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
